<script setup>
import { onMounted, ref, computed, toRaw, watch } from 'vue';
import { ElMessage, ElMessageBox } from 'element-plus';
import { apiClient } from '../../utils/api.js';
import { uploadListingMedia } from '../../api/tools/imageCropper.js';
import { materialBindings, categoryKey } from '../../../../src/shared/workflow-materials.js';
import PageFooterPagination from '../PageFooterPagination.vue';
import WorkflowMaterialInput from './WorkflowMaterialInput.vue';
import WorkflowValuePreview from './WorkflowValuePreview.vue';
import WorkflowBrandModels from './WorkflowBrandModels.vue';
import OzonCategorySelect from './OzonCategorySelect.vue';
const props=defineProps({standalone:Boolean,seed:{type:Object,default:()=>({})},category:{type:Object,default:()=>({})}}),emit=defineEmits(['saved']);
const records=ref([]),keyword=ref(''),busy=ref(false),editor=ref(false),current=ref(null),form=ref({}),preview=ref(null),categoryFilter=ref(''),brandFilter=ref(''),modelFilter=ref(''),formCategoryKey=ref(''),general=ref(false);
const page=ref(1),pageSize=ref(12),total=ref(0),roleFilter=ref(''),catalog=ref([]);let loadSequence=0;
const brandOptions=computed(()=>[...new Set([...catalog.value.map(b=>b.name),...records.value.flatMap(r=>materialBindings(r.payload).map(b=>b.brand))])]);
const modelOptions=computed(()=>[...new Set([...(catalog.value.find(b=>b.name===brandFilter.value)?.models||[]).map(m=>m.name),...records.value.flatMap(r=>materialBindings(r.payload).filter(b=>b.brand===brandFilter.value).flatMap(b=>b.models))])]);
const visible=computed(()=>records.value);
const imageNode=computed(()=>({id:'material_images',type:'images',label:'资料图片',count:form.value.images?.length||1,slots:Array.from({length:form.value.images?.length||1},(_,i)=>`资料图 ${i+1}`)}));
const bindingsLabel=p=>materialBindings(p).map(b=>`${b.brand}：${b.allModels?'全部型号':b.models.join('、')}`).join('；')||'通用资料 · 未限制品牌型号';
async function load(){const sequence=++loadSequence;busy.value=true;try{const query=new URLSearchParams({page:String(page.value),pageSize:String(pageSize.value),keyword:keyword.value,category:categoryFilter.value,brand:brandFilter.value,model:modelFilter.value,role:roleFilter.value});const result=await apiClient.get('/api/product-workflows/material-library?'+query,{noCache:true});if(sequence!==loadSequence)return;records.value=result.items;total.value=result.total;page.value=result.page;}catch(e){if(sequence===loadSequence)ElMessage.error(e.message);}finally{if(sequence===loadSequence)busy.value=false;}}
function search(){page.value=1;load();}
watch([categoryFilter,brandFilter,modelFilter,roleFilter],search);
function edit(record){current.value=record||null;const p=record?.payload;form.value=p?structuredClone({...toRaw(p),name:record.kind==='key_model'?p.label:p.name||record.name,bindings:materialBindings(p)}):{name:'',category:roleFilter.value==='compatibility'?'钥匙模具':'',material:'',role:props.seed.images?.length||roleFilter.value==='compatibility'?'compatibility':'style',notes:'',images:props.seed.images?.length?[...props.seed.images]:[''],bindings:props.seed.bindings||[],listingCategory:categoryKey(props.category)?{key:categoryKey(props.category),name:props.category.categoryName||props.category.name}:null};formCategoryKey.value=categoryKey(form.value.listingCategory);general.value=record?!formCategoryKey.value:false;editor.value=true;}
function selectCategory(chosen){form.value.listingCategory={key:chosen.ozon_category_id,name:chosen.path_zh||chosen.category_name_zh||chosen.category_name||chosen.path||chosen.name};}
async function upload(file,index){busy.value=true;try{const result=await uploadListingMedia(file,{source_module:'product_workflow_material',role:form.value.role}),url=result.publishUrl||result.url||result.previewUrl;if(!url)throw new Error('图片上传未返回地址');form.value.images[index]=url;ElMessage.success('图片已上传，请点击保存到企业资料完成入库');}catch(e){ElMessage.error(e.message);}finally{busy.value=false;}}
async function save(){busy.value=true;try{if(!general.value&&!formCategoryKey.value)throw new Error('请从类目树选择类目，或选择跨类目通用资料');const payload={...form.value,listingCategory:general.value?null:form.value.listingCategory};if(current.value?.kind==='key_model'){const first=payload.bindings[0];Object.assign(payload,{brand:first?.brand||'',model:first?.models?.[0]||'',label:payload.name});}const saved=await apiClient.post(`/api/product-workflows/${current.value?.kind==='key_model'?'key-models':'materials'}`,{id:current.value?.id,revision:current.value?.revision,payload});editor.value=false;await load();emit('saved',saved);ElMessage.success('已保存企业生产资料');}catch(e){ElMessage.error(e.message);}finally{busy.value=false;}}
async function archive(record){try{await ElMessageBox.confirm('停用后不能用于新任务，历史任务保留资料快照。','停用生产资料',{confirmButtonText:'停用',cancelButtonText:'取消',type:'warning'});}catch{return;}busy.value=true;try{await apiClient.post(`/api/product-workflows/${record.kind==='key_model'?'key-models':'materials'}`,{id:record.id,revision:record.revision,payload:{...record.payload,archived:true}});await load();emit('saved');}catch(e){ElMessage.error(e.message);}finally{busy.value=false;}}
onMounted(async()=>{apiClient.get('/api/ai-variant-lab/vehicle-catalog',{noCache:true}).then(result=>catalog.value=result.brands||[]).catch(()=>{});await load();if(props.seed.create)edit();});
</script>
<template>
 <div class="material-library" v-loading="busy"><div class="material-toolbar"><el-input v-model="keyword" clearable placeholder="搜索资料名称、说明、品牌或型号" @keyup.enter="search" @clear="search"/><el-button type="primary" @click="search">搜索</el-button><el-button @click="load">刷新</el-button><el-button type="primary" @click="edit()">新增生产资料</el-button></div><div class="material-filters"><OzonCategorySelect v-model="categoryFilter" :show-sync="false" placeholder="按类目筛选（同时展示通用资料）"/><el-select v-model="brandFilter" clearable filterable placeholder="品牌" @change="modelFilter='' "><el-option v-for="brand in brandOptions" :key="brand" :label="brand" :value="brand"/></el-select><el-select v-model="modelFilter" clearable filterable placeholder="型号" :disabled="!brandFilter"><el-option v-for="model in modelOptions" :key="model" :label="model" :value="model"/></el-select></div><el-radio-group v-model="roleFilter" class="material-kind"><el-radio-button value="">全部资料</el-radio-button><el-radio-button value="compatibility">钥匙模具 / 适配资料</el-radio-button></el-radio-group><p class="hint">资料可选绑定多个品牌和型号；包装、店铺宣传图等可作为通用资料。图片既可作为 AI 参考，也可直接作为成品图使用。</p>
 <el-empty v-if="!visible.length" description="没有匹配资料，可调整筛选或新增"/>
 <div class="material-cards"><article v-for="record in visible" :key="record.id"><WorkflowValuePreview :value="record.payload.images" format="images"/><div><strong>{{ record.name }}</strong><p>{{ record.payload.listingCategory?.name||'通用 / 尚未分类' }} · {{ record.payload.category||record.payload.label||'生产资料' }}</p><small>{{ bindingsLabel(record.payload) }}</small><div><el-button link type="primary" @click="preview=record">预览资料</el-button><el-button link type="primary" @click="edit(record)">编辑</el-button><el-button link type="danger" @click="archive(record)">停用</el-button></div></div></article></div>
 <PageFooterPagination :page="page" :page-size="pageSize" :total="total" :page-sizes="[12,24,48]" :disabled="busy" @update:page="page=$event;load()" @update:page-size="pageSize=$event;search()"/>
 <el-dialog :model-value="Boolean(preview)" @update:model-value="!$event&&(preview=null)" :title="preview?.name||'资料预览'" width="700px" append-to-body><template v-if="preview"><p>{{ preview.payload.listingCategory?.name||'通用资料' }}</p><p>{{ bindingsLabel(preview.payload) }}</p><WorkflowValuePreview :value="preview.payload.images" format="images"/><WorkflowValuePreview :value="preview.payload.notes" label="完整资料说明"/></template></el-dialog>
 <el-dialog v-model="editor" append-to-body :title="current?'编辑生产资料':'新增生产资料'" width="760px" top="4vh" :close-on-click-modal="false" :show-close="!busy" :close-on-press-escape="!busy" class="workflow-material-dialog"><el-form label-position="top" :disabled="busy"><el-form-item label="适用类目"><el-checkbox v-model="general">跨类目通用资料（例如通用礼盒、店铺宣传图）</el-checkbox><OzonCategorySelect v-if="!general" v-model="formCategoryKey" :show-sync="false" :display-label="form.listingCategory?.name||''" @select="selectCategory"/></el-form-item><el-form-item label="资料名称" required><el-input v-model="form.name" placeholder="例如：钥匙模具 A、黑色礼盒成品详情图" maxlength="180"/></el-form-item><el-form-item label="适用品牌和型号（建议绑定，可留空）"><WorkflowBrandModels v-model="form.bindings" :disabled="busy" allow-all/></el-form-item><div class="material-fields"><el-form-item label="材质（选填）"><el-input v-model="form.material" placeholder="只填写已确认的材质"/></el-form-item><el-form-item label="资料类型（自定义）"><el-input v-model="form.category" placeholder="例如：钥匙模具、包装、店铺宣传图"/></el-form-item></div><el-form-item label="参考用途"><el-select v-model="form.role"><el-option label="版式 / 风格参考" value="style"/><el-option label="适配对象参考（例如钥匙模具）" value="compatibility"/><el-option label="真实产品资料" value="product"/></el-select></el-form-item><el-form-item label="资料说明"><el-input v-model="form.notes" type="textarea" :rows="3" placeholder="填写用途、已核实事实和使用限制"/></el-form-item><el-form-item label="资料图片（最多 8 张，支持拖入）"><WorkflowMaterialInput v-model="form.images" compact :node="imageNode" :disabled="busy" @upload="upload"/><el-button :disabled="busy||form.images.length>=8" @click="form.images.push('')">增加图片</el-button></el-form-item></el-form><template #footer><el-button :disabled="busy" @click="editor=false">取消</el-button><el-button type="primary" :loading="busy" @click="save">保存到企业资料</el-button></template></el-dialog></div>
</template>
<style scoped>
.material-library{display:flex;flex-direction:column;height:72vh;min-height:400px;overflow:hidden}.material-toolbar,.material-filters,.material-kind,.hint{flex-shrink:0}.material-kind{margin-top:12px}.material-toolbar{display:flex;gap:10px}.material-toolbar .el-input{max-width:520px;margin-right:auto}.material-filters{display:grid;grid-template-columns:minmax(220px,2fr) 1fr 1fr;gap:12px;margin-top:14px}.hint{color:var(--el-text-color-secondary);font-size:13px;line-height:1.8}.material-cards{display:grid;gap:12px;min-height:0;flex:1;overflow:auto;align-content:start}.material-cards article{display:flex;gap:16px;border:1px solid var(--el-border-color-lighter);border-radius:8px;padding:16px}.material-cards article>.value-preview{width:150px;flex-shrink:0}.material-cards p,.material-cards small{color:var(--el-text-color-secondary);line-height:1.6}.material-cards small{display:block;margin-bottom:12px}.material-fields{display:grid;grid-template-columns:1fr 1fr;gap:16px}.el-select{width:100%}.material-library :deep(.el-form-item__content){display:block}@media(max-width:650px){.material-filters{grid-template-columns:1fr}.material-cards article{flex-wrap:wrap}}
</style>
<style>.workflow-material-dialog .el-dialog__body{max-height:70vh;overflow:auto}</style>
